import{_ as t,o,c as a,ag as n}from"./chunks/framework.8tqBsFWt.js";const c=JSON.parse('{"title":"About VERA","description":"VERA encodes 20 years of agency operating mistakes into software so you never have to make them yourself.","frontmatter":{"title":"About VERA","description":"VERA encodes 20 years of agency operating mistakes into software so you never have to make them yourself."},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md"}'),r={name:"about/index.md"};function i(s,e,h,l,p,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="about-vera" tabindex="-1">About VERA <a class="header-anchor" href="#about-vera" aria-label="Permalink to &quot;About VERA&quot;">​</a></h1><p>VERA wasn&#39;t built in three weeks. The code was written quickly. The thinking behind it took twenty years.</p><p>I&#39;ve spent my career operating professional services businesses in the $1--7M revenue range — the range where every decision is felt personally, where one lost client reshapes the year, and where the owner is usually the bottleneck they&#39;re trying to eliminate. I&#39;ve made every mistake in the book. I&#39;ve hired the wrong seniors and lost the right juniors. I&#39;ve tracked time in spreadsheets that were already lying by the time anyone looked at them. I&#39;ve run retainers that bled margin for months before anyone noticed.</p><p>VERA is the system I wish I&#39;d had. Not a time tracking tool with a chatbot bolted on — an operating system for agencies that encodes the hard-won lessons of running them. Every business rule, every permission boundary, every financial model exists because I learned the cost of getting it wrong.</p><h2 id="what-makes-this-different" tabindex="-1">What makes this different <a class="header-anchor" href="#what-makes-this-different" aria-label="Permalink to &quot;What makes this different&quot;">​</a></h2><p>Most agency tools are built by software engineers who&#39;ve never run an agency. They optimize for data entry. VERA optimizes for the decisions that data should inform — and it puts those decisions in front of the right person at the right time, with the right level of detail for their role.</p><p>The team member sees their hours and their plan. The manager sees their portfolio in percentages. The owner sees the money. Not because the others can&#39;t be trusted, but because showing everyone everything is how you drown an organization in noise.</p><h2 id="the-operating-philosophy" tabindex="-1">The operating philosophy <a class="header-anchor" href="#the-operating-philosophy" aria-label="Permalink to &quot;The operating philosophy&quot;">​</a></h2><p>The sidebar to the left contains the principles that shaped every decision in VERA&#39;s design. They draw on twenty years of practice and the work of people like Greg Crabtree, Peter Senge, David Maister, and Jocko Willink — applied to the specific problem of running a small agency well.</p><p>These aren&#39;t abstract ideas. Each one maps directly to something VERA does:</p><ul><li><p><strong><a href="/about/chapters/01-face-the-truth.html">Face the Truth</a></strong> — VERA shows you the numbers as they are, not as you hope they&#39;ll be. Real-time P&amp;L, burn rates, and capacity gaps surface the moment they happen.</p></li><li><p><strong><a href="/about/chapters/05-the-talent-siphon.html">The Talent Siphon</a></strong> — The allocation and capacity system is built around developing people through projects, not just filling seats. You can see who&#39;s stretched, who&#39;s underused, and who&#39;s ready for more.</p></li><li><p><strong><a href="/about/chapters/06-command-by-intent.html">Command by Intent</a></strong> — VERA&#39;s permission model isn&#39;t about restricting access. It&#39;s about giving each person exactly the information they need to make good decisions autonomously, without drowning them in context that isn&#39;t theirs to carry.</p></li><li><p><strong><a href="/about/chapters/07-the-daily-bookend.html">The Daily Bookend</a></strong> — The morning briefing and evening reminder replace surveillance with rhythm. Your team commits at the start of the day and accounts at the end — VERA handles the structure so you don&#39;t have to chase.</p></li><li><p><strong><a href="/about/chapters/10-labor-efficiency-ratio-the-math-behind-the-philosophy.html">Labor Efficiency Ratio</a></strong> — Every financial model in VERA — retainer burn, sprint accrual, T&amp;M tracking, fixed-price margin — feeds back into the fundamental question: is the work your people do generating enough to sustain them?</p></li></ul><p>These principles aren&#39;t a sales pitch. They&#39;re the lens through which every feature request, every permission rule, and every business rule is evaluated. If it doesn&#39;t serve the operating philosophy, it doesn&#39;t ship.</p><h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><p>You run (or help run) a professional services business with somewhere between 5 and 50 people. You&#39;re past the survival stage but not yet at the scale where enterprise tools make sense. You need to know where the hours go, where the money goes, and whether the two are aligned — without building a reporting infrastructure or hiring someone to maintain it.</p><p>VERA lives in Slack because that&#39;s where your team already is. There&#39;s nothing to log into, no app to open, no form to fill out. You say what you worked on, and the system handles the rest.</p>',15)])])}const m=t(r,[["render",i]]);export{c as __pageData,m as default};
